# ─── STORAGE UTILITIES ────────────────────────────────────────────────────────
PYQ_STORAGE_BASE = "pyq"


def get_pyq_storage_path(grade: int, subject: str, year: int, file_name: str) -> str:
    """Generate clean local path: pyq/class10/mathematics/2022/paper.pdf"""
    clean_sub = re.sub(r"[^a-zA-Z0-9]+", "_", subject.lower().split("(")[0]).strip("_")
    dir_path = os.path.join(PYQ_STORAGE_BASE, f"class{grade}", clean_sub, str(year))
    os.makedirs(dir_path, exist_ok=True)
    return os.path.join(dir_path, file_name)


def compute_file_hash(file_path: str) -> str:
    """SHA-256 hash of a file for duplicate prevention."""
    h = hashlib.sha256()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def download_pdf(source_url: str, dest_path: str, timeout: int = 30) -> bool:
    """
    Downloads a PDF from a catalogued board/archive source URL.
    Returns True if downloaded successfully, False otherwise.
    """
    try:
        req = urllib.request.Request(source_url, headers=REQUEST_HEADERS)
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            if resp.status == 200:
                data = resp.read()
                if len(data) >= 1024 and data.startswith(b"%PDF"):
                    with open(dest_path, "wb") as f:
                        f.write(data)
                    return True
                logger.warning(f"Downloaded payload invalid or too small ({len(data)} bytes) from {source_url}")
                return False
            logger.warning(f"Non-200 HTTP response {resp.status} from {source_url}")
            return False
    except Exception as e:
        logger.warning(f"Download failed for {source_url}: {e}")
        return False


def extract_text_from_pdf(file_path: str) -> Optional[str]:
    """
    Extract selectable text from PDF using PyMuPDF (fitz).
    """
    if not os.path.exists(file_path):
        return None
    try:
        import fitz
        doc = fitz.open(file_path)
        pages_text = []
        for p in doc:
            t = p.get_text("text").strip()
            if t:
                pages_text.append(t)
        doc.close()
        if pages_text:
            return "\n\n--- PAGE BREAK ---\n\n".join(pages_text)
    except Exception as e:
        logger.warning(f"PyMuPDF text extraction failed for {file_path}: {e}")
    return None


def extract_questions_from_text(text: str, default_subject: str, default_grade: int, default_year: int) -> List[Dict[str, Any]]:
    """
    Extract numbered questions from the extracted authentic KSEAB text.
    Handles KSEAB board formatting like '1.', '2.', 'I. Four alternatives...', etc.
    """
    questions = []
    if not text:
        return questions

    # Match numbered items: e.g. "1.\nThe standard form..." or "2. State..."
    pattern = re.compile(
        r"(?:^|\n)\s*(\d{1,2})\.\s+([^\n]+(?:\n(?!\s*\d{1,2}\.).*)*)",
        re.MULTILINE
    )

    matches = pattern.findall(text)
    for num_str, q_body in matches:
        q_clean = " ".join([l.strip() for l in q_body.splitlines() if l.strip()])
        # Filter out headers, pagination, or footer artifacts
        if len(q_clean) >= 20 and not any(k in q_clean for k in ["CCE RF", "Turn over", "Instructions"]):
            # Detect marks if present
            marks_match = re.search(r"[\(\[]\s*(\d+(?:\.\d+)?)\s*(?:marks?|m)\s*[\)\]]", q_clean, re.I)
            marks = float(marks_match.group(1)) if marks_match else 2.0
            questions.append({
                "num": int(num_str),
                "text": q_clean[:400],
                "marks": marks
            })

    return questions
